        return x_min + (x_max - x_min) * (3 * x**2 - 2 * x**3)

gold_answer:
from scipy.special import comb

def smoothclamp(x, x_min=0, x_max=1, N=1):
    if x < x_min:
        return x_min
    if x > x_max:
        return x_max
    x = np.clip((x - x_min) / (x_max - x_min), 0, 1)

    result = 0
    for n in range(0, N + 1):
        result += comb(N + n, n) * comb(2 * N + 1, N - n) * (-x) ** n

    result *= x ** (N + 1)
    return result

llm_response:
def smoothclamp(x, x_min, x_max, N):
    def smoothstep(x):
        return 0 if x <= 0 else 1 if x >= 1 else x**N * (N + 1 - N * x)

    x = (x - x_min) / (x_max - x_min)
    return x_min + smoothstep(x) * (x_max - x_min)

