        if test_case_id == 1:
            df = pd.DataFrame(
                {
                    "A": ["1 &AMP; 1", "BB", "CC", "DD", "1 &AMP; 0"],
                    "B": range(5),
                    "C": ["0 &AMP; 0"] * 5,
                }
