```python
from torch.optim import Optimizer, required


class CustomSGD(Optimizer):

    def __init__(self, params, lr=required, weight_decay=0, nesterov=False):
        if lr is not required and lr < 0.0:
            raise ValueError("Invalid learning rate: {}".format(lr))

        defaults = dict(lr=lr, weight_decay=weight_decay, nesterov=nesterov)
        super(CustomSGD, self).__init__(params, defaults)

    def step(self, closure=None):
        """Performs a single optimization step.
        Arguments:
            closure (callable, optional): A closure that reassesutes the model
                and returns the loss.
        """
        loss = None
        if closure is not None:
            loss = closure()

        for group in self.param_groups:
            weight_decay = group['weight_decay']
            lr = group['lr']

            for p in group['params']:
                if p.grad is None:
                    continue
                d_p = p.grad.data
                if weight_decay != 0:
                    d_p.add_(weight_decay, p.data)

                param_state = self.state[p]
                if 'momentum_buffer' not in param_state:
                    buf = param_state['momentum_buffer'] = torch.zeros_like(d_p)
                else:
                    buf = param_state['momentum_buffer']
                buf.mul_(0).add_(1, d_p)

                if group['nesterov']:
                    d_p = d_p.add(lr, buf)
                else:
                    d_p = d_p - lr * buf

                p.data.add_(d_p)
        return loss
