            df = pd.DataFrame(
                data=[[34, "null", "mark"], [22, "null", "mark"], [34, "null", "mark"]],
                columns=["id", "temp", "name"],
                index=[1, 2, 3],
            )
        if test_case_id == 2:
            df = pd.DataFrame(
                data=[
                    [34, "null", "mark"],
                    [22, "null", "mark"],
                    [34, "null", "mark"],
                    [21, "null", "mark"],
                ],
                columns=["id", "temp", "name"],
                index=[1, 2, 3, 4],
            )
        return df

    test_input = define_test_input(test_case_id)
    expected_result = generate_ans(copy.deepcopy(test_input))
